import{M as e,O as t,f as n,m as r,s as i,u as a}from"./runtime-core.esm-bundler-DwmdDY9i.js";import{t as o}from"./plugin-vue_export-helper-BDNMzG2s.js";var s=JSON.parse(`{"path":"/01-Infrastructure/zOS/Concepts/02-major-components-of-the-zos-system.html","title":"Lesson 2: z/OS 시스템의 주요 구성 요소","lang":"ko-KR","frontmatter":{"description":"이 글은 z/OS 시스템의 주요 구성 요소에 대한 내용으로, 서브시스템과 시스템 구성 요소들을 다룹니다.","tag":["mainframe","zos","subsystems","components"],"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Lesson 2: z/OS 시스템의 주요 구성 요소\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-01-02T09:28:19.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://docmoa.github.io/01-Infrastructure/zOS/Concepts/02-major-components-of-the-zos-system.html"}],["meta",{"property":"og:site_name","content":"docmoa"}],["meta",{"property":"og:title","content":"Lesson 2: z/OS 시스템의 주요 구성 요소"}],["meta",{"property":"og:description","content":"이 글은 z/OS 시스템의 주요 구성 요소에 대한 내용으로, 서브시스템과 시스템 구성 요소들을 다룹니다."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"ko-KR"}],["meta",{"property":"og:updated_time","content":"2026-01-02T09:28:19.000Z"}],["meta",{"property":"article:tag","content":"components"}],["meta",{"property":"article:tag","content":"subsystems"}],["meta",{"property":"article:tag","content":"zos"}],["meta",{"property":"article:tag","content":"mainframe"}],["meta",{"property":"article:modified_time","content":"2026-01-02T09:28:19.000Z"}]]},"git":{"createdTime":1767346099000,"updatedTime":1767346099000,"contributors":[{"name":"Great-Stone","username":"Great-Stone","email":"hahohh@gmail.com","commits":1,"url":"https://github.com/Great-Stone"}]},"readingTime":{"minutes":43.88,"words":2633},"filePathRelative":"01-Infrastructure/zOS/Concepts/02-major-components-of-the-zos-system.md","excerpt":"\\n<h2>개요</h2>\\n<p>이 모듈은 운영 체제와 결합하여 완전한 컴퓨팅 환경을 위한 시설을 제공하는 많은 제품들을 탐구합니다.</p>\\n<h2>학습 목표</h2>\\n<p>이 모듈을 완료한 후, 다음을 수행할 수 있습니다:</p>\\n<ul>\\n<li>가장 널리 사용되는 z/OS 시스템 구성 요소의 이름과 기능을 식별할 수 있습니다.</li>\\n</ul>\\n<h2>Subsystems (서브시스템)</h2>\\n<h3>Subsystem의 정의</h3>\\n<p>z/OS가 최적의 효율성으로 작동하려면 많은 프로그램과 구성 요소가 필요합니다. 이러한 구성 요소 중 일부는 <code>subsystem(서브시스템)</code>이라고 불립니다.</p>"}`),c={name:`02-major-components-of-the-zos-system.md`};function l(o,s,c,l,u,d){let f=e(`Mermaid`);return t(),a(`div`,null,[s[0]||=n(`<h1 id="lesson-2-z-os-시스템의-주요-구성-요소" tabindex="-1"><a class="header-anchor" href="#lesson-2-z-os-시스템의-주요-구성-요소"><span>Lesson 2: z/OS 시스템의 주요 구성 요소</span></a></h1><h2 id="개요" tabindex="-1"><a class="header-anchor" href="#개요"><span>개요</span></a></h2><p>이 모듈은 운영 체제와 결합하여 완전한 컴퓨팅 환경을 위한 시설을 제공하는 많은 제품들을 탐구합니다.</p><h2 id="학습-목표" tabindex="-1"><a class="header-anchor" href="#학습-목표"><span>학습 목표</span></a></h2><p>이 모듈을 완료한 후, 다음을 수행할 수 있습니다:</p><ul><li>가장 널리 사용되는 z/OS 시스템 구성 요소의 이름과 기능을 식별할 수 있습니다.</li></ul><h2 id="subsystems-서브시스템" tabindex="-1"><a class="header-anchor" href="#subsystems-서브시스템"><span>Subsystems (서브시스템)</span></a></h2><h3 id="subsystem의-정의" tabindex="-1"><a class="header-anchor" href="#subsystem의-정의"><span>Subsystem의 정의</span></a></h3><p>z/OS가 최적의 효율성으로 작동하려면 많은 프로그램과 구성 요소가 필요합니다. 이러한 구성 요소 중 일부는 <code>subsystem(서브시스템)</code>이라고 불립니다.</p><p><code>Subsystem</code>은 다른 구성 요소와 비동기적으로 작동하는 시스템 구성 요소입니다. 이 맥락에서, 일반적으로 사용자나 다른 프로그램의 요청에 대해 작동하는 프로그램을 의미합니다.</p>`,10),r(f,{code:``}),s[1]||=n(`<h3 id="primary-subsystem-주-서브시스템" tabindex="-1"><a class="header-anchor" href="#primary-subsystem-주-서브시스템"><span>Primary Subsystem (주 서브시스템)</span></a></h3><p>모든 z/OS 설치에는 <code>주 서브시스템(Primary Subsystem)</code>이 필요합니다. 이는 <code>Job Entry Subsystem (작업 입력 서브시스템)</code>으로, 일반적으로 <code>JES2</code> 또는 <code>JES3</code>입니다.</p><h4 id="jes-job-entry-subsystem" tabindex="-1"><a class="header-anchor" href="#jes-job-entry-subsystem"><span>JES (Job Entry Subsystem)</span></a></h4><p>JES는 작업 입력 및 출력을 관리하는 필수 서브시스템입니다. JES의 주요 기능은 다음과 같습니다:</p><ul><li><strong>작업 입력 관리</strong>: JCL(Job Control Language)을 읽고 처리합니다.</li><li><strong>SPOOL 관리</strong>: 작업 입력과 출력을 SPOOL 데이터셋에 저장합니다.</li><li><strong>작업 스케줄링</strong>: 작업을 실행할 수 있도록 스케줄링합니다.</li><li><strong>출력 관리</strong>: 작업 출력을 프린터나 다른 출력 장치로 전달합니다.</li></ul><div class="hint-container tip"><p class="hint-container-title">Primary Subsystem</p><p>모든 z/OS 설치에는 주 서브시스템인 Job Entry Subsystem(예: JES2)이 필요합니다.</p></div><h3 id="secondary-subsystems-보조-서브시스템" tabindex="-1"><a class="header-anchor" href="#secondary-subsystems-보조-서브시스템"><span>Secondary Subsystems (보조 서브시스템)</span></a></h3><p>주 서브시스템 외에도, z/OS 시스템에는 다양한 <code>보조 서브시스템(Secondary Subsystems)</code>이 설치될 수 있습니다. 이들은 선택적이지만, 시스템의 기능과 효율성을 크게 향상시킵니다.</p><h4 id="sms-storage-management-subsystem" tabindex="-1"><a class="header-anchor" href="#sms-storage-management-subsystem"><span>SMS (Storage Management Subsystem)</span></a></h4><p><code>SMS (저장소 관리 서브시스템)</code>는 데이터셋의 자동 관리와 저장소 할당을 제공합니다. SMS는 여러 구성 요소를 포함하며, 그 중 HSM(Hierarchical Storage Manager)이 계층적 저장소 관리를 담당합니다.</p><p>주요 기능:</p><ul><li><strong>자동 데이터셋 관리</strong>: 데이터셋의 자동 생성 및 관리</li><li><strong>저장소 클래스 관리</strong>: 저장소 클래스에 따른 자동 할당</li><li><strong>데이터셋 마이그레이션</strong>: 데이터셋의 자동 마이그레이션 (HSM을 통해)</li><li><strong>계층적 저장소 관리</strong>: HSM을 통한 다단계 저장소 계층 관리</li></ul><div class="hint-container tip"><p class="hint-container-title">SMS와 HSM의 관계</p><p>SMS는 저장소 관리를 위한 통합 시스템이며, HSM은 SMS의 구성 요소 중 하나로 계층적 저장소 관리를 담당합니다. 자세한 내용은 아래 &quot;SMS/HSM&quot; 섹션을 참조하세요.</p></div><h4 id="racf-resource-access-control-facility" tabindex="-1"><a class="header-anchor" href="#racf-resource-access-control-facility"><span>RACF (Resource Access Control Facility)</span></a></h4><p><code>RACF (리소스 접근 제어 시설)</code>는 z/OS 시스템의 보안을 관리합니다.</p><p>주요 기능:</p><ul><li><strong>사용자 인증</strong>: 사용자 식별 및 인증</li><li><strong>권한 관리</strong>: 리소스에 대한 접근 권한 관리</li><li><strong>감사 추적</strong>: 보안 이벤트 로깅 및 감사</li></ul><h4 id="wlm-workload-manager" tabindex="-1"><a class="header-anchor" href="#wlm-workload-manager"><span>WLM (Workload Manager)</span></a></h4><p><code>WLM (작업 부하 관리자)</code>는 시스템 리소스를 관리하고 작업 부하를 최적화합니다.</p><p>주요 기능:</p><ul><li><strong>작업 부하 관리</strong>: 시스템 리소스의 효율적 분배</li><li><strong>성능 목표 설정</strong>: 서비스 클래스에 따른 성능 목표 관리</li><li><strong>리소스 모니터링</strong>: 시스템 리소스 사용량 모니터링</li></ul><h3 id="subsystem의-작동-방식" tabindex="-1"><a class="header-anchor" href="#subsystem의-작동-방식"><span>Subsystem의 작동 방식</span></a></h3><p>Subsystem은 다음과 같은 방식으로 작동합니다:</p><ol><li><strong>비동기적 작동</strong>: Subsystem은 다른 구성 요소와 독립적으로 비동기적으로 작동합니다.</li><li><strong>요청 처리</strong>: 사용자나 다른 프로그램의 요청을 받아 처리합니다.</li><li><strong>리소스 관리</strong>: 각 Subsystem은 특정 리소스나 기능을 관리합니다.</li></ol>`,24),r(f,{code:``}),s[2]||=n(`<h3 id="subsystem의-중요성" tabindex="-1"><a class="header-anchor" href="#subsystem의-중요성"><span>Subsystem의 중요성</span></a></h3><p>Subsystem은 z/OS 시스템의 핵심 구성 요소로서:</p><ul><li><strong>모듈화</strong>: 시스템 기능을 모듈화하여 관리 용이성 향상</li><li><strong>확장성</strong>: 필요한 기능만 선택적으로 설치 가능</li><li><strong>유지보수</strong>: 각 Subsystem을 독립적으로 업데이트 및 유지보수 가능</li><li><strong>효율성</strong>: 특화된 기능을 제공하여 시스템 효율성 향상</li></ul><div class="hint-container tip"><p class="hint-container-title">Subsystem 요약</p><ul><li><strong>Subsystem</strong>: 다른 구성 요소와 비동기적으로 작동하는 시스템 구성 요소</li><li><strong>Primary Subsystem</strong>: 모든 z/OS 설치에 필수 (JES2 또는 JES3)</li><li><strong>Secondary Subsystems</strong>: 선택적이지만 시스템 기능 향상을 위해 설치됨 <ul><li>SMS: 저장소 관리 (HSM 포함)</li><li>RACF: 보안 및 접근 제어</li><li>WLM: 작업 부하 관리</li></ul></li></ul></div><h2 id="job-control-language-jcl" tabindex="-1"><a class="header-anchor" href="#job-control-language-jcl"><span>Job Control Language (JCL)</span></a></h2><h3 id="jcl의-정의" tabindex="-1"><a class="header-anchor" href="#jcl의-정의"><span>JCL의 정의</span></a></h3><p><code>Job Control Language (JCL)</code>는 운영 체제의 일부로, 작업의 리소스 요구 사항을 정의하는 언어입니다. JCL은 z/OS 시스템의 핵심 언어입니다.</p><h3 id="jcl의-역할" tabindex="-1"><a class="header-anchor" href="#jcl의-역할"><span>JCL의 역할</span></a></h3><p>JCL은 각 배치 작업(batch job), 시작된 작업(started task), 또는 TSO/E 사용자에 의해 요구되는 리소스를 정의합니다. JCL은 다음을 정의합니다:</p><ul><li><strong>프로그램(Programs)</strong>: 실행할 프로그램</li><li><strong>루틴(Routines)</strong>: 실행할 CLISTs 또는 REXX 루틴</li><li><strong>데이터 할당(Data allocation)</strong>: 사용할 데이터셋</li><li><strong>우선순위(Priorities)</strong>: 실행 우선순위</li><li><strong>출력(Printing)</strong>: 출력 우선순위 및 출력 대상</li></ul><h3 id="jcl의-중요성" tabindex="-1"><a class="header-anchor" href="#jcl의-중요성"><span>JCL의 중요성</span></a></h3><p>z/OS 시스템에서 시작되는 모든 작업은 컴퓨터를 지시하기 위해 JCL이 필요합니다. JCL 없이는 작업이 실행되지 않습니다.</p><h3 id="jcl-예제" tabindex="-1"><a class="header-anchor" href="#jcl-예제"><span>JCL 예제</span></a></h3><p>다음은 JCL의 예제입니다:</p><div class="language-jcl line-numbers-mode" data-highlighter="prismjs" data-ext="jcl"><pre><code class="language-jcl"><span class="line">//JIEBCPY1 JOB MSGCLASS=C,NOTIFY=JPDTS4</span>
<span class="line">//STEP1 EXEC PGM=IEBCOPY</span>
<span class="line">//SYSPRINT DD SYSOUT=*</span>
<span class="line">//INDSET DD DSN=XPROD.JCL.MASTER,DISP=SHR</span>
<span class="line">//OUTDSET DD DSN=JPDTS4.JCL.CNTL,DISP=(,CATLG),UNIT=SYSDA,</span>
<span class="line">// SPACE=(TRK,(2,2,2))</span>
<span class="line">//SYSIN DD *</span>
<span class="line">COPY INDD=INDSET,OUTDD=OUTDSET</span>
<span class="line">SELECT MEMBER=(AATEST)</span>
<span class="line">/*</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="jcl-예제-설명" tabindex="-1"><a class="header-anchor" href="#jcl-예제-설명"><span>JCL 예제 설명</span></a></h4><p>이 JCL 예제는 다음과 같은 작업을 수행합니다:</p><ol><li><p><strong>JOB 문</strong>: <code>//JIEBCPY1 JOB MSGCLASS=C,NOTIFY=JPDTS4</code></p><ul><li>작업 이름: JIEBCPY1</li><li>메시지 클래스: C</li><li>완료 시 알림 대상: JPDTS4</li></ul></li><li><p><strong>EXEC 문</strong>: <code>//STEP1 EXEC PGM=IEBCOPY</code></p><ul><li>단계 이름: STEP1</li><li>실행할 프로그램: IEBCOPY (데이터셋 복사 유틸리티)</li></ul></li><li><p><strong>DD 문들</strong>:</p><ul><li><code>//SYSPRINT DD SYSOUT=*</code>: 출력을 시스템 출력으로 전송</li><li><code>//INDSET DD DSN=XPROD.JCL.MASTER,DISP=SHR</code>: 입력 데이터셋 지정</li><li><code>//OUTDSET DD DSN=JPDTS4.JCL.CNTL,DISP=(,CATLG),UNIT=SYSDA,SPACE=(TRK,(2,2,2))</code>: 출력 데이터셋 지정 및 할당</li><li><code>//SYSIN DD *</code>: 제어 입력 스트림 시작</li></ul></li><li><p><strong>제어 명령</strong>:</p><ul><li><code>COPY INDD=INDSET,OUTDD=OUTDSET</code>: 데이터셋 복사 명령</li><li><code>SELECT MEMBER=(AATEST)</code>: 특정 멤버 선택</li><li><code>/*</code>: 제어 입력 스트림 종료</li></ul></li></ol><h3 id="jcl이-지시하는-사항" tabindex="-1"><a class="header-anchor" href="#jcl이-지시하는-사항"><span>JCL이 지시하는 사항</span></a></h3><p>JCL은 다음과 같은 사항들을 지시합니다:</p>`,20),r(f,{code:``}),s[3]||=n(`<h3 id="jcl의-주요-구성-요소" tabindex="-1"><a class="header-anchor" href="#jcl의-주요-구성-요소"><span>JCL의 주요 구성 요소</span></a></h3><h4 id="job-문" tabindex="-1"><a class="header-anchor" href="#job-문"><span>JOB 문</span></a></h4><p>JOB 문은 작업을 정의하고 작업 레벨 파라미터를 지정합니다.</p><p>주요 파라미터:</p><ul><li><strong>MSGCLASS</strong>: 메시지 출력 클래스</li><li><strong>NOTIFY</strong>: 작업 완료 시 알림을 받을 사용자 ID</li><li><strong>CLASS</strong>: 작업 클래스 (실행 우선순위 결정)</li></ul><h4 id="exec-문" tabindex="-1"><a class="header-anchor" href="#exec-문"><span>EXEC 문</span></a></h4><p>EXEC 문은 작업 단계(step)를 정의하고 실행할 프로그램을 지정합니다.</p><p>주요 파라미터:</p><ul><li><strong>PGM</strong>: 실행할 프로그램 이름</li><li><strong>PROC</strong>: 실행할 프로시저 이름</li></ul><h4 id="dd-문" tabindex="-1"><a class="header-anchor" href="#dd-문"><span>DD 문</span></a></h4><p>DD(Data Definition) 문은 데이터셋을 정의하고 할당합니다.</p><p>주요 파라미터:</p><ul><li><strong>DSN</strong>: 데이터셋 이름</li><li><strong>DISP</strong>: 데이터셋 처리 방법 (SHR, OLD, NEW, MOD 등)</li><li><strong>UNIT</strong>: 장치 유형</li><li><strong>SPACE</strong>: 저장소 할당량</li><li><strong>SYSOUT</strong>: 시스템 출력 클래스</li></ul><h3 id="jcl-처리-과정" tabindex="-1"><a class="header-anchor" href="#jcl-처리-과정"><span>JCL 처리 과정</span></a></h3>`,14),r(f,{code:``}),s[4]||=n(`<h3 id="jcl의-특징" tabindex="-1"><a class="header-anchor" href="#jcl의-특징"><span>JCL의 특징</span></a></h3><ol><li><strong>필수성</strong>: z/OS 시스템에서 모든 작업은 JCL이 필요합니다.</li><li><strong>표준화</strong>: 작업 실행을 위한 표준화된 방법을 제공합니다.</li><li><strong>리소스 정의</strong>: 작업에 필요한 모든 리소스를 명시적으로 정의합니다.</li><li><strong>유연성</strong>: 다양한 작업 유형과 요구 사항을 지원합니다.</li></ol><div class="hint-container tip"><p class="hint-container-title">JCL 요약</p><ul><li><strong>JCL (Job Control Language)</strong>: 작업의 리소스 요구 사항을 정의하는 언어</li><li><strong>필수 구성 요소</strong>: JOB 문, EXEC 문, DD 문</li><li><strong>주요 기능</strong>: <ul><li>실행할 프로그램 및 루틴 지정</li><li>데이터셋 할당 및 관리</li><li>실행 우선순위 설정</li><li>출력 관리</li></ul></li><li><strong>중요성</strong>: JCL 없이는 z/OS 시스템에서 작업이 실행되지 않습니다.</li></ul></div><h2 id="tso-e-and-ispf" tabindex="-1"><a class="header-anchor" href="#tso-e-and-ispf"><span>TSO/E and ISPF</span></a></h2><h3 id="tso와-tso-e의-관계" tabindex="-1"><a class="header-anchor" href="#tso와-tso-e의-관계"><span>TSO와 TSO/E의 관계</span></a></h3><p><code>TSO (Time Sharing Option)</code>는 <code>TSO/E (Time Sharing Option/Extensions)</code>의 전신(predecessor)입니다. TSO는 라인 에디터(line editor)와 멀티태스킹 및 유틸리티 기능을 사용했습니다.</p><h3 id="tso-e-time-sharing-option-extensions" tabindex="-1"><a class="header-anchor" href="#tso-e-time-sharing-option-extensions"><span>TSO/E (Time Sharing Option/Extensions)</span></a></h3><p><code>TSO/E</code>는 프로그래머나 운영자가 z/OS 프로그램과 대화형으로 작업할 수 있게 해주는 도구입니다.</p><h4 id="tso-e의-진화" tabindex="-1"><a class="header-anchor" href="#tso-e의-진화"><span>TSO/E의 진화</span></a></h4>`,9),r(f,{code:``}),s[5]||=n(`<p>TSO는 초기에 라인 에디터와 멀티태스킹 및 유틸리티 기능을 사용했습니다. 이 라인 에디터는 <code>Interactive System Productivity Facility (ISPF)</code>에서 찾을 수 있는 더 정교한 전체 화면 에디터로 대체되었습니다.</p><h3 id="ispf-interactive-system-productivity-facility" tabindex="-1"><a class="header-anchor" href="#ispf-interactive-system-productivity-facility"><span>ISPF (Interactive System Productivity Facility)</span></a></h3><p><code>ISPF</code>는 TSO/E 하에서 실행되며 TSO/E 유틸리티를 실행하기 위한 메뉴 기반 인터페이스를 제공합니다.</p><div class="hint-container tip"><p class="hint-container-title">ISPF runs under TSO/E</p><p>ISPF는 TSO/E 하에서 실행되며 메뉴 기반 인터페이스를 제공합니다.</p></div><h4 id="ispf의-주요-기능" tabindex="-1"><a class="header-anchor" href="#ispf의-주요-기능"><span>ISPF의 주요 기능</span></a></h4><p>ISPF를 통해 다음을 수행할 수 있습니다:</p><ul><li><strong>데이터셋 생성</strong>: 데이터셋을 생성하고 관리합니다</li><li><strong>소스 코드 작성</strong>: 소스 코드를 작성하고 편집합니다</li><li><strong>JCL 작성</strong>: Job Control Language를 작성하고 편집합니다</li><li><strong>작업 제출</strong>: z/OS 시스템에 작업을 제출합니다</li></ul>`,7),r(f,{code:``}),s[6]||=n(`<h3 id="tso-e와-ispf의-통합" tabindex="-1"><a class="header-anchor" href="#tso-e와-ispf의-통합"><span>TSO/E와 ISPF의 통합</span></a></h3><p>TSO/E는 많은 유용한 유틸리티 기능을 제공하며, 이러한 기능들은 ISPF를 통해 쉽게 구성되고 간단하게 실행될 수 있습니다.</p><h4 id="ispf의-장점" tabindex="-1"><a class="header-anchor" href="#ispf의-장점"><span>ISPF의 장점</span></a></h4><ol><li><strong>전체 화면 인터페이스</strong>: 라인 에디터보다 사용하기 쉬운 전체 화면 편집 환경</li><li><strong>메뉴 기반</strong>: 명령어를 외울 필요 없이 메뉴를 통해 기능에 접근</li><li><strong>통합 환경</strong>: 데이터셋 편집, 소스 코드 작성, JCL 작성, 작업 제출을 하나의 환경에서 수행</li><li><strong>생산성 향상</strong>: 프로그래머와 운영자의 작업 효율성을 크게 향상</li></ol><h3 id="tso-e와-ispf의-작동-방식" tabindex="-1"><a class="header-anchor" href="#tso-e와-ispf의-작동-방식"><span>TSO/E와 ISPF의 작동 방식</span></a></h3>`,5),r(f,{code:``}),s[7]||=n(`<h3 id="ispf의-중요성" tabindex="-1"><a class="header-anchor" href="#ispf의-중요성"><span>ISPF의 중요성</span></a></h3><p>대부분의 z/OS 설치에서 작업하는 사람들은 ISPF 사용 방법을 알아야 합니다. ISPF는 z/OS 환경에서 작업하는 데 필수적인 도구입니다.</p><h4 id="ispf를-통한-일반적인-작업" tabindex="-1"><a class="header-anchor" href="#ispf를-통한-일반적인-작업"><span>ISPF를 통한 일반적인 작업</span></a></h4><ol><li><strong>데이터셋 관리</strong>: 데이터셋 생성, 편집, 삭제, 복사</li><li><strong>소스 코드 개발</strong>: 프로그램 소스 코드 작성 및 편집</li><li><strong>JCL 작성</strong>: 작업 제출을 위한 JCL 작성 및 편집</li><li><strong>작업 제출 및 모니터링</strong>: 배치 작업 제출 및 상태 확인</li><li><strong>시스템 유틸리티 실행</strong>: 다양한 시스템 유틸리티에 접근</li></ol><h3 id="tso-e와-ispf의-관계-요약" tabindex="-1"><a class="header-anchor" href="#tso-e와-ispf의-관계-요약"><span>TSO/E와 ISPF의 관계 요약</span></a></h3><ul><li><strong>TSO</strong>: TSO/E의 전신으로, 라인 에디터와 기본 유틸리티를 제공</li><li><strong>TSO/E</strong>: z/OS 프로그램과 대화형으로 작업할 수 있게 해주는 확장된 도구</li><li><strong>ISPF</strong>: TSO/E 하에서 실행되는 메뉴 기반 인터페이스로, 전체 화면 편집 및 다양한 유틸리티 접근 제공</li></ul><div class="hint-container tip"><p class="hint-container-title">TSO/E and ISPF 요약</p><ul><li><strong>TSO</strong>: TSO/E의 전신, 라인 에디터 사용</li><li><strong>TSO/E</strong>: 프로그래머나 운영자가 z/OS 프로그램과 대화형으로 작업할 수 있게 해주는 도구</li><li><strong>ISPF</strong>: TSO/E 하에서 실행되는 메뉴 기반 인터페이스</li><li><strong>주요 기능</strong> (ISPF를 통해): <ul><li>데이터셋 생성</li><li>소스 코드 생성</li><li>JCL 생성</li><li>z/OS 시스템에 작업 제출</li></ul></li><li><strong>중요성</strong>: 대부분의 z/OS 설치에서 작업하는 사람들은 ISPF 사용 방법을 알아야 합니다.</li></ul></div><h2 id="vtam-and-tcp-ip" tabindex="-1"><a class="header-anchor" href="#vtam-and-tcp-ip"><span>VTAM and TCP/IP</span></a></h2><h3 id="vtam-virtual-telecommunications-access-method" tabindex="-1"><a class="header-anchor" href="#vtam-virtual-telecommunications-access-method"><span>VTAM (Virtual Telecommunications Access Method)</span></a></h3><p><code>VTAM (Virtual Telecommunications Access Method)</code>는 &quot;vee-tam&quot;으로 발음되며, 채널과 LAN 연결 장치(터미널 등) 간의 데이터 전송을 관리하고 <code>System Network Architecture (SNA)</code> 라우팅 작업을 수행합니다.</p><h4 id="vtam의-역할" tabindex="-1"><a class="header-anchor" href="#vtam의-역할"><span>VTAM의 역할</span></a></h4><p>VTAM은 통신 프로그램과 터미널 또는 애플리케이션 프로그램 간의 통신을 중개합니다. CICS, TSO/E와 같은 통신 프로그램들은 적절한 터미널과 애플리케이션 프로그램으로 정보를 전달하기 위해 VTAM에 의존합니다.</p>`,12),r(f,{code:``}),s[8]||=i(`h4`,{id:`vtam의-데이터-흐름`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#vtam의-데이터-흐름`},[i(`span`,null,`VTAM의 데이터 흐름`)])],-1),s[9]||=i(`p`,null,`데이터는 터미널에서 VTAM을 통해 메인프레임에서 실행 중인 애플리케이션으로 전송됩니다. 애플리케이션이 데이터를 처리한 후, 처리된 데이터는 다시 VTAM을 통해 해당 터미널에 적합한 형식으로 반환됩니다.`,-1),r(f,{code:``}),s[10]||=n(`<h4 id="vtam-시작" tabindex="-1"><a class="header-anchor" href="#vtam-시작"><span>VTAM 시작</span></a></h4><p>VTAM은 운영자가 시작하는 프로그램입니다. 운영자는 일반적으로 <code>S NET</code> 명령을 입력하여 VTAM을 시작합니다.</p><div class="hint-container tip"><p class="hint-container-title">VTAM 시작 명령</p><p>IBM은 VTAM 프로그램의 프로시저 이름을 <code>NET</code>으로 지정했기 때문에, 운영자는 <code>S NET</code>을 입력하여 VTAM을 시작합니다. 일부 설치에서는 IBM 기본값을 사용하지 않고 다른 이름을 할당할 수 있습니다.</p></div><div class="hint-container tip"><p class="hint-container-title">VTAM 프로그램과 프로시저 이름</p><p>프로그램은 VTAM이라고 불리지만, IBM은 프로시저 이름을 <code>NET</code>으로 지정했습니다. 따라서 <code>S NET</code> 명령을 사용하여 VTAM 프로그램 세트를 시작합니다.</p></div><h3 id="tcp-ip" tabindex="-1"><a class="header-anchor" href="#tcp-ip"><span>TCP/IP</span></a></h3><p><code>TCP/IP</code>는 네트워크 관리자로, VTAM과는 달리 IBM 전용이 아닙니다. 기본 기능은 VTAM과 동일합니다. 즉, 애플리케이션과 사용자 간에 데이터를 주고받는 것입니다.</p><h4 id="tcp-ip의-특징" tabindex="-1"><a class="header-anchor" href="#tcp-ip의-특징"><span>TCP/IP의 특징</span></a></h4><p>TCP/IP와 VTAM의 주요 차이점 중 하나는 TCP/IP가 비독점 표준이라는 것입니다. 이는 메인프레임 시스템 외에도 다른 시스템을 가진 설치에 매력적입니다.</p>`,8),r(f,{code:`eJxLy8kvT85ILCpRCHHiUgCCEOcAz4BoJSCl7xmgFAsWAxOhfp4R0UogEirqk5lXWhGtBKagQlH+wdFKVfr+wVB+eGZeSn55cbQSlIFsHtgiBRtdXbuaN9Mmvt6w8u20pQpv27a+6V5QA7aMsCqw1YSVAV1FWBHUhQj3FZdU5qRC9aRl5uRYKRsYmJklJ+sk5+fkF1kpp6WlIakDORiqzNjYGLsasHMJKQI6FqrEzMwMuxKoU7GbBACo+5u9`}),s[11]||=n(`<h4 id="tcp-ip의-역할" tabindex="-1"><a class="header-anchor" href="#tcp-ip의-역할"><span>TCP/IP의 역할</span></a></h4><p>TCP/IP는 다양한 운영 체제 간의 통신을 가능하게 합니다:</p><ul><li><strong>UNIX 시스템</strong>: TCP/IP를 통해 z/OS와 통신</li><li><strong>Linux 시스템</strong>: TCP/IP를 통해 z/OS와 통신</li><li><strong>Windows 시스템</strong>: TCP/IP를 통해 z/OS와 통신</li><li><strong>z/OS</strong>: 다른 시스템과 TCP/IP를 통해 통신</li></ul><h3 id="vtam과-tcp-ip의-통합" tabindex="-1"><a class="header-anchor" href="#vtam과-tcp-ip의-통합"><span>VTAM과 TCP/IP의 통합</span></a></h3><p>VTAM과 TCP/IP는 <code>z/OS Communications Server</code>라는 단일 제품으로 통합되었습니다.</p><h4 id="z-os-communications-server" tabindex="-1"><a class="header-anchor" href="#z-os-communications-server"><span>z/OS Communications Server</span></a></h4><p>z/OS Communications Server는 VTAM과 TCP/IP의 기능을 통합하여 제공합니다:</p><ul><li><strong>VTAM 기능</strong>: SNA 네트워크를 통한 통신 지원</li><li><strong>TCP/IP 기능</strong>: 표준 TCP/IP 네트워크를 통한 통신 지원</li><li><strong>통합 관리</strong>: 단일 인터페이스를 통한 네트워크 관리</li></ul>`,8),r(f,{code:``}),s[12]||=n(`<h3 id="vtam과-tcp-ip-비교" tabindex="-1"><a class="header-anchor" href="#vtam과-tcp-ip-비교"><span>VTAM과 TCP/IP 비교</span></a></h3><table><thead><tr><th>특징</th><th>VTAM</th><th>TCP/IP</th></tr></thead><tbody><tr><td><strong>제조사</strong></td><td>IBM 전용</td><td>비독점 표준</td></tr><tr><td><strong>주요 용도</strong></td><td>SNA 네트워크 통신</td><td>표준 네트워크 통신</td></tr><tr><td><strong>지원 시스템</strong></td><td>주로 IBM 메인프레임</td><td>다양한 운영 체제</td></tr><tr><td><strong>라우팅</strong></td><td>SNA 라우팅</td><td>IP 라우팅</td></tr><tr><td><strong>통합 제품</strong></td><td>z/OS Communications Server</td><td>z/OS Communications Server</td></tr></tbody></table><h3 id="vtam과-tcp-ip의-중요성" tabindex="-1"><a class="header-anchor" href="#vtam과-tcp-ip의-중요성"><span>VTAM과 TCP/IP의 중요성</span></a></h3><p>VTAM과 TCP/IP는 z/OS 시스템의 네트워크 통신을 위한 핵심 구성 요소입니다:</p><ol><li><strong>통신 중개</strong>: 애플리케이션과 터미널 간의 통신을 중개합니다</li><li><strong>데이터 라우팅</strong>: 데이터를 적절한 대상으로 라우팅합니다</li><li><strong>프로토콜 지원</strong>: 다양한 네트워크 프로토콜을 지원합니다</li><li><strong>시스템 통합</strong>: 다양한 시스템 간의 통신을 가능하게 합니다</li></ol><div class="hint-container tip"><p class="hint-container-title">VTAM and TCP/IP 요약</p><ul><li><p><strong>VTAM (Virtual Telecommunications Access Method)</strong>:</p><ul><li>&quot;vee-tam&quot;으로 발음</li><li>채널과 LAN 연결 장치 간의 데이터 전송 관리</li><li>SNA 라우팅 작업 수행</li><li>CICS, TSO/E 같은 통신 프로그램이 의존</li><li>운영자가 <code>S NET</code> 명령으로 시작</li></ul></li><li><p><strong>TCP/IP</strong>:</p><ul><li>비독점 표준 네트워크 프로토콜</li><li>다양한 운영 체제 간 통신 지원</li><li>UNIX, Linux, Windows와 z/OS 간 통신 가능</li></ul></li><li><p><strong>z/OS Communications Server</strong>:</p><ul><li>VTAM과 TCP/IP를 통합한 단일 제품</li><li>SNA 및 표준 TCP/IP 네트워크 모두 지원</li></ul></li></ul></div><h2 id="the-system-log-syslog" tabindex="-1"><a class="header-anchor" href="#the-system-log-syslog"><span>The System Log (SYSLOG)</span></a></h2><h3 id="syslog의-정의" tabindex="-1"><a class="header-anchor" href="#syslog의-정의"><span>SYSLOG의 정의</span></a></h3><p>시스템 로그 또는 <code>SYSLOG</code>는 프로그램, 운영자, 시스템 간의 통신을 기록하는 데 사용됩니다.</p><h3 id="syslog의-내용" tabindex="-1"><a class="header-anchor" href="#syslog의-내용"><span>SYSLOG의 내용</span></a></h3><p>SYSLOG에는 다음과 같은 정보가 기록됩니다:</p><h4 id="syslog에-기록되는-정보-유형" tabindex="-1"><a class="header-anchor" href="#syslog에-기록되는-정보-유형"><span>SYSLOG에 기록되는 정보 유형</span></a></h4><ol><li><strong>운영자 작업</strong>: 마운트 요청과 같은 운영자 작업</li><li><strong>비정상적인 이벤트</strong>: 시프트 중 발생한 비정상적인 이벤트에 대한 설명</li><li><strong>작업 시간</strong>: 작업의 시작 및 완료 시간</li><li><strong>운영 데이터</strong>: 문제 프로그램이 <code>Write-To-Log (WTL)</code> 매크로 명령을 사용하여 입력한 운영 데이터</li><li><strong>WTO 및 WTOR 메시지</strong>: <ul><li><code>Write-To-Operator (WTO)</code> 메시지</li><li><code>Write-To-Operator-With-Reply (WTOR)</code> 메시지</li></ul></li><li><strong>WTOR 응답</strong>: 수락된 WTOR 메시지 응답</li><li><strong>운영자 응답</strong>: 운영자가 제공한 응답</li><li><strong>작업 중단 메시지</strong>: 작업 중단(abend) 메시지</li><li><strong>운영 체제 명령</strong>: 콘솔과 입력 스트림을 통해 운영 체제가 발행한 명령</li></ol><h3 id="syslog-접근-방법" tabindex="-1"><a class="header-anchor" href="#syslog-접근-방법"><span>SYSLOG 접근 방법</span></a></h3><p>SYSLOG는 보통 <code>SDSF (System Display and Search Facility)</code>에서 <code>LOG</code>를 입력하여 접근할 수 있습니다.</p>`,15),r(f,{code:``}),s[13]||=n(`<h3 id="syslog의-역할" tabindex="-1"><a class="header-anchor" href="#syslog의-역할"><span>SYSLOG의 역할</span></a></h3><p>SYSLOG는 z/OS 시스템 운영에서 중요한 역할을 합니다:</p><ol><li><strong>통신 기록</strong>: 프로그램, 운영자, 시스템 간의 모든 통신을 기록</li><li><strong>문제 진단</strong>: 시스템 문제를 진단하고 해결하는 데 필요한 정보 제공</li><li><strong>감사 추적</strong>: 운영자 작업 및 시스템 이벤트에 대한 감사 추적</li><li><strong>작업 모니터링</strong>: 작업 실행 상태 및 완료 시간 추적</li><li><strong>이벤트 분석</strong>: 비정상적인 이벤트 및 시스템 동작 분석</li></ol><h3 id="syslog의-중요성" tabindex="-1"><a class="header-anchor" href="#syslog의-중요성"><span>SYSLOG의 중요성</span></a></h3><p>SYSLOG는 z/OS 시스템의 운영 및 유지보수를 위한 필수 도구입니다:</p><ul><li><strong>시스템 상태 파악</strong>: 현재 시스템 상태 및 이벤트 확인</li><li><strong>문제 해결</strong>: 시스템 문제 발생 시 원인 분석</li><li><strong>성능 모니터링</strong>: 시스템 성능 및 작업 실행 시간 모니터링</li><li><strong>보안 감사</strong>: 시스템 접근 및 작업에 대한 보안 감사</li></ul><div class="hint-container tip"><p class="hint-container-title">SYSLOG 요약</p><ul><li><strong>SYSLOG</strong>: 시스템 로그로, 프로그램, 운영자, 시스템 간의 통신을 기록</li><li><strong>주요 내용</strong>: <ul><li>운영자 작업 및 응답</li><li>작업 시작 및 완료 시간</li><li>WTO 및 WTOR 메시지</li><li>작업 중단(abend) 메시지</li><li>운영 체제 명령</li><li>비정상적인 이벤트 설명</li></ul></li><li><strong>접근 방법</strong>: SDSF에서 <code>LOG</code> 명령을 입력하여 접근</li><li><strong>용도</strong>: 시스템 문제 진단, 감사 추적, 작업 모니터링</li></ul></div><h2 id="system-automation-시스템-자동화" tabindex="-1"><a class="header-anchor" href="#system-automation-시스템-자동화"><span>System Automation (시스템 자동화)</span></a></h2><h3 id="system-automation의-정의" tabindex="-1"><a class="header-anchor" href="#system-automation의-정의"><span>System Automation의 정의</span></a></h3><p>많은 조직이 이제 다양한 시스템의 콘솔에서 나오는 메시지를 상관관계 분석하고, 메시지를 필터링하며, 일상적인 문제에 필요한 응답과 작업을 자동화하는 형태의 시스템 자동화에 의존하고 있습니다.</p><h3 id="system-automation의-작동-방식" tabindex="-1"><a class="header-anchor" href="#system-automation의-작동-방식"><span>System Automation의 작동 방식</span></a></h3><p>System Automation은 여러 콘솔에서 메시지를 수집하고, 메시지를 필터링한 후, 필요한 작업을 자동으로 수행하거나 다른 콘솔로 메시지를 전송합니다.</p>`,12),r(f,{code:``}),s[14]||=n(`<h4 id="system-automation의-처리-과정" tabindex="-1"><a class="header-anchor" href="#system-automation의-처리-과정"><span>System Automation의 처리 과정</span></a></h4><ol><li><strong>메시지 수신 (In)</strong>: 여러 콘솔에서 메시지를 수신합니다</li><li><strong>메시지 필터링 (Filtering messages)</strong>: 수신된 메시지를 분석하고 필터링합니다</li><li><strong>자동화 처리</strong>: 필터링된 메시지에 따라 필요한 작업을 자동으로 수행합니다</li><li><strong>메시지/액션 전송 (Out)</strong>: 처리 결과를 다른 콘솔로 전송하거나 필요한 액션을 실행합니다</li></ol><h3 id="system-automation의-주요-기능" tabindex="-1"><a class="header-anchor" href="#system-automation의-주요-기능"><span>System Automation의 주요 기능</span></a></h3><p>System Automation은 다음과 같은 기능을 제공합니다:</p><ol><li><strong>메시지 상관관계 분석</strong>: 다양한 시스템의 콘솔에서 나오는 메시지를 수집하고 상관관계를 분석합니다</li><li><strong>메시지 필터링</strong>: 중요한 메시지와 일반적인 메시지를 구분하여 필터링합니다</li><li><strong>자동 응답</strong>: 일상적인 문제에 대해 자동으로 응답합니다</li><li><strong>자동 작업 수행</strong>: 정의된 규칙에 따라 작업을 자동으로 수행합니다</li><li><strong>콘솔 통합 관리</strong>: 여러 콘솔의 메시지를 중앙에서 관리합니다</li></ol><h3 id="system-automation-제품-예시" tabindex="-1"><a class="header-anchor" href="#system-automation-제품-예시"><span>System Automation 제품 예시</span></a></h3><p>시장에는 여러 System Automation 제품이 있습니다:</p><ul><li><strong>IBM Z System Automation</strong>: IBM의 시스템 자동화 제품</li><li><strong>Broadcom&#39;s OPS/MVS Event Management &amp; Automation</strong>: Broadcom의 이벤트 관리 및 자동화 제품</li><li><strong>BMC AMI Ops</strong>: BMC의 운영 자동화 제품</li></ul><h3 id="system-automation의-이점" tabindex="-1"><a class="header-anchor" href="#system-automation의-이점"><span>System Automation의 이점</span></a></h3><p>System Automation을 사용하면 다음과 같은 이점을 얻을 수 있습니다:</p><ol><li><strong>운영 효율성 향상</strong>: 일상적인 작업을 자동화하여 운영 효율성을 향상시킵니다</li><li><strong>응답 시간 단축</strong>: 자동화된 응답으로 문제 해결 시간을 단축합니다</li><li><strong>인적 오류 감소</strong>: 자동화된 처리로 인적 오류를 감소시킵니다</li><li><strong>24/7 모니터링</strong>: 시스템을 지속적으로 모니터링하고 자동으로 대응합니다</li><li><strong>리소스 최적화</strong>: 운영자 리소스를 더 중요한 작업에 집중시킬 수 있습니다</li></ol><h3 id="system-automation의-작동-흐름" tabindex="-1"><a class="header-anchor" href="#system-automation의-작동-흐름"><span>System Automation의 작동 흐름</span></a></h3>`,12),r(f,{code:``}),s[15]||=n(`<h3 id="system-automation의-중요성" tabindex="-1"><a class="header-anchor" href="#system-automation의-중요성"><span>System Automation의 중요성</span></a></h3><p>현대의 z/OS 환경에서는 System Automation이 필수적인 구성 요소가 되었습니다:</p><ul><li><strong>복잡성 관리</strong>: 여러 시스템과 콘솔의 복잡성을 관리합니다</li><li><strong>일상 작업 자동화</strong>: 반복적인 일상 작업을 자동화합니다</li><li><strong>문제 예방</strong>: 문제를 사전에 감지하고 자동으로 대응합니다</li><li><strong>운영 비용 절감</strong>: 운영 비용을 절감하고 효율성을 향상시킵니다</li></ul><div class="hint-container tip"><p class="hint-container-title">System Automation 요약</p><ul><li><strong>System Automation</strong>: 여러 시스템의 콘솔 메시지를 상관관계 분석하고 필터링하며 자동화하는 시스템</li><li><strong>작동 방식</strong>: <ul><li>여러 콘솔에서 메시지 수신 (In)</li><li>메시지 필터링 및 분석</li><li>자동 응답 및 작업 수행</li><li>다른 콘솔로 메시지/액션 전송 (Out)</li></ul></li><li><strong>주요 제품</strong>: <ul><li>IBM Z System Automation</li><li>Broadcom&#39;s OPS/MVS Event Management &amp; Automation</li><li>BMC AMI Ops</li></ul></li><li><strong>이점</strong>: 운영 효율성 향상, 응답 시간 단축, 인적 오류 감소, 24/7 모니터링</li></ul></div><h2 id="cics-customer-information-control-system" tabindex="-1"><a class="header-anchor" href="#cics-customer-information-control-system"><span>CICS (Customer Information Control System)</span></a></h2><h3 id="cics의-정의" tabindex="-1"><a class="header-anchor" href="#cics의-정의"><span>CICS의 정의</span></a></h3><p><code>CICS (Customer Information Control System)</code>는 고속 트랜잭션 처리 시스템으로, 다양한 산업 분야에서 중요한 역할을 합니다.</p><h3 id="cics의-기능" tabindex="-1"><a class="header-anchor" href="#cics의-기능"><span>CICS의 기능</span></a></h3><p>CICS는 VTAM 또는 TCP/IP와 함께 작동하여 터미널에서 입력된 트랜잭션을 애플리케이션 프로그램에 의해 동시에 처리할 수 있게 합니다.</p>`,9),r(f,{code:``}),s[16]||=n(`<h3 id="cics의-성능" tabindex="-1"><a class="header-anchor" href="#cics의-성능"><span>CICS의 성능</span></a></h3><p>CICS는 초당 수천 개의 트랜잭션을 처리할 수 있어서, 고속의 안전한 데이터 접근이 필요한 환경에 이상적입니다.</p><h3 id="cics의-주요-사용-사례" tabindex="-1"><a class="header-anchor" href="#cics의-주요-사용-사례"><span>CICS의 주요 사용 사례</span></a></h3><p>CICS는 다음과 같은 분야에서 널리 사용됩니다:</p><ol><li><strong>은행</strong>: 텔러 시스템에서 고객 거래 처리</li><li><strong>정부</strong>: 고객 지원 시스템</li><li><strong>항공사</strong>: 예약 시스템</li><li><strong>기타 조직</strong>: 고속의 안전한 데이터 접근이 필요한 모든 조직</li></ol><h3 id="cics와-통신-방법" tabindex="-1"><a class="header-anchor" href="#cics와-통신-방법"><span>CICS와 통신 방법</span></a></h3><p>CICS는 다음과 같은 통신 방법을 사용합니다:</p><ul><li><strong>VTAM</strong>: Virtual Telecommunications Access Method를 통한 통신</li><li><strong>TCP/IP</strong>: 표준 TCP/IP 프로토콜을 통한 통신</li></ul><h3 id="cics가-지원하는-프로그래밍-언어" tabindex="-1"><a class="header-anchor" href="#cics가-지원하는-프로그래밍-언어"><span>CICS가 지원하는 프로그래밍 언어</span></a></h3><p>CICS는 다양한 프로그래밍 언어로 작성된 애플리케이션 프로그램과 함께 작동할 수 있습니다:</p><ul><li><strong>Assembler</strong>: 어셈블리 언어</li><li><strong>Java</strong>: 자바 언어</li><li><strong>REXX</strong>: REXX 스크립트 언어</li><li><strong>C, C++</strong>: C 및 C++ 언어</li><li><strong>COBOL</strong>: COBOL 언어</li><li><strong>PL/I</strong>: PL/I 언어</li><li><strong>IDMS</strong>: IDMS 데이터베이스 시스템</li></ul><h3 id="cics의-트랜잭션-처리-과정" tabindex="-1"><a class="header-anchor" href="#cics의-트랜잭션-처리-과정"><span>CICS의 트랜잭션 처리 과정</span></a></h3>`,12),r(f,{code:``}),s[17]||=n(`<h3 id="cics의-특징" tabindex="-1"><a class="header-anchor" href="#cics의-특징"><span>CICS의 특징</span></a></h3><ol><li><strong>고속 처리</strong>: 초당 수천 개의 트랜잭션 처리 가능</li><li><strong>동시 처리</strong>: 여러 트랜잭션을 동시에 처리</li><li><strong>다양한 언어 지원</strong>: 여러 프로그래밍 언어로 작성된 애플리케이션 지원</li><li><strong>안전한 데이터 접근</strong>: 안전한 데이터 접근 보장</li><li><strong>통신 유연성</strong>: VTAM 또는 TCP/IP를 통한 통신 지원</li></ol><h3 id="cics의-중요성" tabindex="-1"><a class="header-anchor" href="#cics의-중요성"><span>CICS의 중요성</span></a></h3><p>CICS는 현대의 엔터프라이즈 환경에서 필수적인 트랜잭션 처리 시스템입니다:</p><ul><li><strong>실시간 처리</strong>: 실시간으로 트랜잭션을 처리하여 즉각적인 응답 제공</li><li><strong>고가용성</strong>: 높은 가용성과 안정성 제공</li><li><strong>확장성</strong>: 대규모 트랜잭션 부하를 처리할 수 있는 확장성</li><li><strong>보안</strong>: 안전한 데이터 접근 및 트랜잭션 처리</li><li><strong>통합</strong>: 다양한 시스템과 통합 가능</li></ul><div class="hint-container tip"><p class="hint-container-title">CICS 요약</p><ul><li><strong>CICS (Customer Information Control System)</strong>: 고속 트랜잭션 처리 시스템</li><li><strong>주요 기능</strong>: <ul><li>VTAM 또는 TCP/IP와 함께 작동하여 터미널 트랜잭션 처리</li><li>초당 수천 개의 트랜잭션 처리 가능</li><li>다양한 프로그래밍 언어로 작성된 애플리케이션 지원</li></ul></li><li><strong>주요 사용 사례</strong>: <ul><li>은행 텔러 시스템</li><li>정부 고객 지원</li><li>항공사 예약 시스템</li><li>고속의 안전한 데이터 접근이 필요한 조직</li></ul></li><li><strong>지원 언어</strong>: Assembler, Java, REXX, C/C++, COBOL, PL/I, IDMS</li><li><strong>통신 방법</strong>: VTAM 또는 TCP/IP</li></ul></div><h2 id="ims-information-management-system" tabindex="-1"><a class="header-anchor" href="#ims-information-management-system"><span>IMS (Information Management System)</span></a></h2><h3 id="ims의-정의" tabindex="-1"><a class="header-anchor" href="#ims의-정의"><span>IMS의 정의</span></a></h3><p><code>IMS (Information Management System)</code>는 IBM의 온라인 애플리케이션 및 데이터베이스 관리 시스템입니다. IMS는 CICS의 트랜잭션 처리 기능과 IBM Db2의 데이터베이스 관리 기능을 함께 제공합니다.</p><h3 id="ims의-아키텍처" tabindex="-1"><a class="header-anchor" href="#ims의-아키텍처"><span>IMS의 아키텍처</span></a></h3><p>IMS는 VTAM/TCP/IP와 함께 작동하며, 여러 데이터베이스와 양방향으로 통신합니다.</p>`,11),r(f,{code:``}),s[18]||=n(`<h3 id="ims의-주요-기능" tabindex="-1"><a class="header-anchor" href="#ims의-주요-기능"><span>IMS의 주요 기능</span></a></h3><p>IMS는 다음과 같은 기능을 제공합니다:</p><ol><li><strong>트랜잭션 처리</strong>: CICS와 유사한 트랜잭션 처리 기능</li><li><strong>데이터베이스 관리</strong>: Db2와 유사한 데이터베이스 관리 기능</li><li><strong>온라인 애플리케이션 지원</strong>: 온라인 애플리케이션 실행 환경 제공</li><li><strong>다중 데이터베이스 지원</strong>: 여러 데이터베이스와 동시에 통신 가능</li><li><strong>통신 지원</strong>: VTAM/TCP/IP를 통한 통신 지원</li></ol><h3 id="ims의-특징" tabindex="-1"><a class="header-anchor" href="#ims의-특징"><span>IMS의 특징</span></a></h3><ul><li><strong>통합 솔루션</strong>: 트랜잭션 처리와 데이터베이스 관리를 하나의 시스템으로 통합</li><li><strong>고성능</strong>: 대규모 트랜잭션 처리 및 데이터베이스 작업 지원</li><li><strong>안정성</strong>: 엔터프라이즈급 안정성과 가용성 제공</li><li><strong>확장성</strong>: 대규모 데이터베이스 환경 지원</li></ul><h3 id="ims와-cics-db2의-비교" tabindex="-1"><a class="header-anchor" href="#ims와-cics-db2의-비교"><span>IMS와 CICS, Db2의 비교</span></a></h3><table><thead><tr><th>기능</th><th>IMS</th><th>CICS</th><th>Db2</th></tr></thead><tbody><tr><td><strong>트랜잭션 처리</strong></td><td>✓</td><td>✓</td><td>-</td></tr><tr><td><strong>데이터베이스 관리</strong></td><td>✓</td><td>-</td><td>✓</td></tr><tr><td><strong>온라인 애플리케이션</strong></td><td>✓</td><td>✓</td><td>-</td></tr><tr><td><strong>통합 솔루션</strong></td><td>✓</td><td>-</td><td>-</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">IMS 요약</p><ul><li><strong>IMS (Information Management System)</strong>: 온라인 애플리케이션 및 데이터베이스 관리 시스템</li><li><strong>주요 기능</strong>: <ul><li>CICS의 트랜잭션 처리 기능 제공</li><li>IBM Db2의 데이터베이스 관리 기능 제공</li><li>VTAM/TCP/IP를 통한 통신 지원</li><li>여러 데이터베이스와 양방향 통신</li></ul></li><li><strong>특징</strong>: 트랜잭션 처리와 데이터베이스 관리를 통합한 솔루션</li></ul></div><h2 id="db2" tabindex="-1"><a class="header-anchor" href="#db2"><span>Db2</span></a></h2><h3 id="db2의-정의" tabindex="-1"><a class="header-anchor" href="#db2의-정의"><span>Db2의 정의</span></a></h3><p><code>Db2</code>는 <code>Structured Query Language (SQL)</code> 구문으로 구동되는 관계형 데이터베이스 관리 시스템입니다.</p><h3 id="db2의-진화" tabindex="-1"><a class="header-anchor" href="#db2의-진화"><span>Db2의 진화</span></a></h3><p>Db2는 원래 단순한 구조화된 데이터를 처리하기 위해 개발되었지만, 오늘날의 증가하는 정보 및 데이터 요구 사항으로 인해 크로스 플랫폼에서 실행되고 이미지, 텍스트, 비디오, 대용량 객체, XML과 같은 다양한 데이터 타입을 처리할 수 있는 제품군으로 발전했습니다.</p><h3 id="db2-데이터베이스-구성-요소" tabindex="-1"><a class="header-anchor" href="#db2-데이터베이스-구성-요소"><span>Db2 데이터베이스 구성 요소</span></a></h3><p>Db2 데이터베이스는 다음과 같은 구성 요소를 포함합니다:</p><ol><li><strong>Tables (테이블)</strong>: 데이터를 저장하는 기본 구조</li><li><strong>Tables spaces (테이블스페이스)</strong>: 테이블이 저장되는 논리적 저장소 영역</li><li><strong>Storage groups (스토리지 그룹)</strong>: 물리적 저장소 장치를 그룹화한 것</li><li><strong>Views (뷰)</strong>: 하나 이상의 테이블에서 데이터를 추출한 논리적 표현</li><li><strong>Indexes (인덱스)</strong>: 데이터 검색 성능을 향상시키는 구조</li></ol><h3 id="db2의-주요-특징" tabindex="-1"><a class="header-anchor" href="#db2의-주요-특징"><span>Db2의 주요 특징</span></a></h3><ol><li><strong>관계형 데이터베이스</strong>: SQL을 사용한 관계형 데이터베이스 관리</li><li><strong>크로스 플랫폼</strong>: 다양한 플랫폼에서 실행 가능</li><li><strong>다양한 데이터 타입 지원</strong>: <ul><li>구조화된 데이터</li><li>이미지</li><li>텍스트</li><li>비디오</li><li>대용량 객체 (Large Objects)</li><li>XML</li></ul></li><li><strong>고성능</strong>: 대규모 데이터 처리 및 고성능 쿼리 처리</li><li><strong>확장성</strong>: 엔터프라이즈급 확장성 제공</li></ol><h3 id="db2의-사용-사례" tabindex="-1"><a class="header-anchor" href="#db2의-사용-사례"><span>Db2의 사용 사례</span></a></h3><p>Db2는 다음과 같은 환경에서 사용됩니다:</p><ul><li><strong>엔터프라이즈 데이터베이스</strong>: 대규모 기업의 핵심 데이터베이스</li><li><strong>데이터 웨어하우스</strong>: 대용량 데이터 분석 및 저장</li><li><strong>온라인 트랜잭션 처리 (OLTP)</strong>: 실시간 트랜잭션 처리</li><li><strong>비즈니스 인텔리전스</strong>: 비즈니스 분석 및 리포팅</li><li><strong>하이브리드 데이터</strong>: 구조화된 데이터와 비구조화된 데이터의 통합 관리</li></ul><h3 id="db2의-중요성" tabindex="-1"><a class="header-anchor" href="#db2의-중요성"><span>Db2의 중요성</span></a></h3><p>Db2는 현대의 데이터 중심 환경에서 필수적인 데이터베이스 관리 시스템입니다:</p><ul><li><strong>데이터 통합</strong>: 다양한 형태의 데이터를 통합 관리</li><li><strong>성능 최적화</strong>: 고성능 데이터 처리 및 쿼리 최적화</li><li><strong>안정성</strong>: 엔터프라이즈급 안정성과 가용성</li><li><strong>보안</strong>: 강력한 데이터 보안 및 접근 제어</li><li><strong>유연성</strong>: 다양한 데이터 타입과 플랫폼 지원</li></ul><div class="hint-container tip"><p class="hint-container-title">Db2 요약</p><ul><li><strong>Db2</strong>: SQL로 구동되는 관계형 데이터베이스 관리 시스템</li><li><strong>주요 구성 요소</strong>: <ul><li>Tables (테이블)</li><li>Tables spaces (테이블스페이스)</li><li>Storage groups (스토리지 그룹)</li><li>Views (뷰)</li><li>Indexes (인덱스)</li></ul></li><li><strong>지원 데이터 타입</strong>: 구조화된 데이터, 이미지, 텍스트, 비디오, 대용량 객체, XML</li><li><strong>특징</strong>: 크로스 플랫폼 지원, 고성능, 확장성, 다양한 데이터 타입 처리</li></ul></div><h2 id="ibm-mq" tabindex="-1"><a class="header-anchor" href="#ibm-mq"><span>IBM MQ</span></a></h2><h3 id="ibm-mq의-정의" tabindex="-1"><a class="header-anchor" href="#ibm-mq의-정의"><span>IBM MQ의 정의</span></a></h3><p><code>IBM MQ</code>는 <code>MQSeries</code>라는 MVS 제품에서 시작되었으며, 종종 단순히 <code>MQ</code>라고 불립니다. MQ는 <code>Message Queuing (메시지 큐잉)</code>을 의미합니다.</p><h3 id="ibm-mq의-목적" tabindex="-1"><a class="header-anchor" href="#ibm-mq의-목적"><span>IBM MQ의 목적</span></a></h3><p>IBM MQ의 목적은 프로그램이 z/OS, Windows, UNIX 또는 기타 여러 플랫폼에서 실행되는 다른 시스템의 다른 프로그램과 메시지를 주고받을 수 있게 하는 것입니다.</p><h3 id="ibm-mq-네트워크-아키텍처" tabindex="-1"><a class="header-anchor" href="#ibm-mq-네트워크-아키텍처"><span>IBM MQ 네트워크 아키텍처</span></a></h3><p>IBM MQ는 다양한 플랫폼 간의 메시지 통신을 지원합니다.</p>`,32),r(f,{code:``}),s[19]||=n(`<h3 id="ibm-mq의-작동-방식" tabindex="-1"><a class="header-anchor" href="#ibm-mq의-작동-방식"><span>IBM MQ의 작동 방식</span></a></h3><p>IBM MQ는 메시지 큐잉을 통해 비동기 메시지 통신을 제공합니다:</p><ol><li><strong>메시지 전송</strong>: 한 시스템의 프로그램이 메시지를 큐에 전송</li><li><strong>메시지 큐잉</strong>: 메시지가 큐에 저장됨</li><li><strong>메시지 수신</strong>: 다른 시스템의 프로그램이 큐에서 메시지를 수신</li></ol><h3 id="ibm-mq의-특징" tabindex="-1"><a class="header-anchor" href="#ibm-mq의-특징"><span>IBM MQ의 특징</span></a></h3><ol><li><strong>플랫폼 독립성</strong>: 다양한 운영 체제와 플랫폼 간 통신 지원</li><li><strong>비동기 통신</strong>: 프로그램이 직접 연결되지 않아도 메시지 교환 가능</li><li><strong>신뢰성</strong>: 메시지 전달 보장 및 오류 처리</li><li><strong>확장성</strong>: 대규모 메시지 처리 지원</li><li><strong>유연성</strong>: 다양한 애플리케이션 통합 지원</li></ol><h3 id="ibm-mq의-사용-사례" tabindex="-1"><a class="header-anchor" href="#ibm-mq의-사용-사례"><span>IBM MQ의 사용 사례</span></a></h3><p>IBM MQ는 다음과 같은 환경에서 사용됩니다:</p><ul><li><strong>엔터프라이즈 통합</strong>: 다양한 시스템 간의 메시지 통신</li><li><strong>비동기 처리</strong>: 비동기 작업 처리 및 이벤트 기반 아키텍처</li><li><strong>시스템 간 통신</strong>: 서로 다른 플랫폼의 시스템 간 통신</li><li><strong>메시지 브로커</strong>: 메시지 라우팅 및 변환</li></ul><div class="hint-container tip"><p class="hint-container-title">IBM MQ 요약</p><ul><li><strong>IBM MQ</strong>: Message Queuing을 의미하며, MQSeries에서 시작</li><li><strong>목적</strong>: 다양한 플랫폼(z/OS, Windows, UNIX, Linux 등)에서 실행되는 프로그램 간 메시지 통신</li><li><strong>주요 특징</strong>: <ul><li>플랫폼 독립성</li><li>비동기 통신</li><li>신뢰성 있는 메시지 전달</li><li>확장성 및 유연성</li></ul></li><li><strong>사용 사례</strong>: 엔터프라이즈 통합, 비동기 처리, 시스템 간 통신</li></ul></div><h2 id="security-보안" tabindex="-1"><a class="header-anchor" href="#security-보안"><span>Security (보안)</span></a></h2><h3 id="z-os-보안의-특징" tabindex="-1"><a class="header-anchor" href="#z-os-보안의-특징"><span>z/OS 보안의 특징</span></a></h3><p>z/OS 자체는 사용자 ID 및 비밀번호 관리나 데이터셋 보안과 같은 보안 기능을 제공하지 않습니다. 이러한 기능은 별도의 보안 제품에 의해 수행됩니다.</p><h3 id="보안-제품" tabindex="-1"><a class="header-anchor" href="#보안-제품"><span>보안 제품</span></a></h3><p>z/OS 환경에서 보안을 제공하는 주요 제품들은 다음과 같습니다:</p>`,14),r(f,{code:``}),s[20]||=n(`<h3 id="ibm-security-server-racf" tabindex="-1"><a class="header-anchor" href="#ibm-security-server-racf"><span>IBM Security Server (RACF)</span></a></h3><p>IBM은 <code>IBM Security Server</code> 제품을 제공하며, 이는 종종 주요 구성 요소 중 하나인 <code>Resource Access Control Facility (RACF)</code>로 불립니다.</p><h4 id="racf의-주요-기능" tabindex="-1"><a class="header-anchor" href="#racf의-주요-기능"><span>RACF의 주요 기능</span></a></h4><ul><li><strong>사용자 인증</strong>: 사용자 ID 및 비밀번호 관리</li><li><strong>리소스 접근 제어</strong>: 데이터셋 및 기타 리소스에 대한 접근 제어</li><li><strong>권한 관리</strong>: 사용자 및 그룹 권한 관리</li><li><strong>감사 추적</strong>: 보안 이벤트 로깅 및 감사</li></ul><h3 id="broadcom-보안-제품" tabindex="-1"><a class="header-anchor" href="#broadcom-보안-제품"><span>Broadcom 보안 제품</span></a></h3><p>Broadcom은 두 가지 보안 제품을 제공합니다:</p><ol><li><strong>ACF2</strong>: Broadcom의 보안 제품</li><li><strong>Top Secret</strong>: Broadcom의 보안 제품</li></ol><h3 id="보안-제품의-역할" tabindex="-1"><a class="header-anchor" href="#보안-제품의-역할"><span>보안 제품의 역할</span></a></h3><p>보안 제품은 다음과 같은 역할을 수행합니다:</p><ol><li><strong>사용자 인증</strong>: 사용자 ID 및 비밀번호 관리</li><li><strong>접근 제어</strong>: 데이터셋 및 시스템 리소스에 대한 접근 제어</li><li><strong>권한 관리</strong>: 사용자 권한 및 그룹 권한 관리</li><li><strong>보안 정책 적용</strong>: 조직의 보안 정책 적용 및 강제</li><li><strong>감사 및 로깅</strong>: 보안 이벤트 감사 및 로깅</li></ol><h3 id="보안-제품의-작동-방식" tabindex="-1"><a class="header-anchor" href="#보안-제품의-작동-방식"><span>보안 제품의 작동 방식</span></a></h3>`,11),r(f,{code:``}),s[21]||=n(`<h3 id="보안-제품의-중요성" tabindex="-1"><a class="header-anchor" href="#보안-제품의-중요성"><span>보안 제품의 중요성</span></a></h3><p>보안 제품은 z/OS 환경에서 필수적인 구성 요소입니다:</p><ul><li><strong>데이터 보호</strong>: 중요한 데이터를 무단 접근으로부터 보호</li><li><strong>규정 준수</strong>: 보안 규정 및 정책 준수</li><li><strong>감사 추적</strong>: 보안 이벤트 추적 및 감사</li><li><strong>접근 제어</strong>: 세밀한 접근 제어 및 권한 관리</li><li><strong>사용자 관리</strong>: 사용자 계정 및 인증 관리</li></ul><h3 id="보안-제품-비교" tabindex="-1"><a class="header-anchor" href="#보안-제품-비교"><span>보안 제품 비교</span></a></h3><table><thead><tr><th>제품</th><th>제공업체</th><th>주요 특징</th></tr></thead><tbody><tr><td><strong>RACF</strong></td><td>IBM</td><td>IBM Security Server의 주요 구성 요소</td></tr><tr><td><strong>ACF2</strong></td><td>Broadcom</td><td>Broadcom의 보안 제품</td></tr><tr><td><strong>Top Secret</strong></td><td>Broadcom</td><td>Broadcom의 보안 제품</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">Security 요약</p><ul><li><strong>z/OS 보안</strong>: z/OS 자체는 보안 기능을 제공하지 않음</li><li><strong>보안 제품 필요</strong>: 별도의 보안 제품이 필요함</li><li><strong>주요 보안 제품</strong>: <ul><li><strong>IBM Security Server (RACF)</strong>: IBM의 보안 제품</li><li><strong>Broadcom&#39;s ACF2</strong>: Broadcom의 보안 제품</li><li><strong>Broadcom&#39;s Top Secret</strong>: Broadcom의 보안 제품</li></ul></li><li><strong>주요 기능</strong>: <ul><li>사용자 ID 및 비밀번호 관리</li><li>데이터셋 보안 및 접근 제어</li><li>권한 관리 및 감사 추적</li></ul></li></ul></div><h2 id="sms-hsm-storage-management-subsystem-hierarchical-storage-manager" tabindex="-1"><a class="header-anchor" href="#sms-hsm-storage-management-subsystem-hierarchical-storage-manager"><span>SMS/HSM (Storage Management Subsystem / Hierarchical Storage Manager)</span></a></h2><h3 id="sms-storage-management-subsystem-의-정의" tabindex="-1"><a class="header-anchor" href="#sms-storage-management-subsystem-의-정의"><span>SMS (Storage Management Subsystem)의 정의</span></a></h3><p><code>SMS (Storage Management Subsystem)</code>는 다양한 기존 IBM 제품을 통합하여 자동 공간 관리를 제공하는 시스템입니다. SMS는 데이터셋의 자동 관리, 저장소 할당, 그리고 계층적 저장소 관리를 포함합니다.</p><h3 id="hsm-hierarchical-storage-manager" tabindex="-1"><a class="header-anchor" href="#hsm-hierarchical-storage-manager"><span>HSM (Hierarchical Storage Manager)</span></a></h3><p><code>HSM (Hierarchical Storage Manager)</code>는 SMS의 구성 요소 중 하나로, <code>DFSMShsm</code>으로도 알려져 있습니다. SMS의 구성 요소 중 운영자에게 가장 잘 보이는 부분이며, 계층적 저장소 관리를 담당합니다.</p><p>HSM은 선택적인 z/OS 기능으로, 자주 접근되지 않는 데이터를 더 느리고 저렴한 저장소 미디어(테이프 포함)로 이동시켜 DASD의 공간을 자동으로 제어합니다. 이를 통해 더 빠르고 비용이 많이 드는 장치의 공간을 확보하여 더 자주 사용되는 데이터에 빠른 접근을 제공할 수 있습니다.</p><h3 id="hsm의-작동-방식" tabindex="-1"><a class="header-anchor" href="#hsm의-작동-방식"><span>HSM의 작동 방식</span></a></h3><p>HSM은 공간 사용률 또는 데이터 연령을 기반으로 한 사전 정의된 임계값을 사용하여 참조되지 않은 데이터를 PRIMARY(일반) DASD에서 HSM Level 1 DASD의 압축 형식으로 이동시킵니다.</p><h3 id="계층적-저장소-구조" tabindex="-1"><a class="header-anchor" href="#계층적-저장소-구조"><span>계층적 저장소 구조</span></a></h3><p>HSM은 3단계 계층적 저장소 구조를 사용합니다:</p>`,16),r(f,{code:``}),s[22]||=n(`<h4 id="저장소-계층-설명" tabindex="-1"><a class="header-anchor" href="#저장소-계층-설명"><span>저장소 계층 설명</span></a></h4><ol><li><p><strong>Primary volumes (주 저장소)</strong>:</p><ul><li>가장 빠르고 비용이 많이 드는 저장소</li><li>자주 사용되는 데이터 저장</li><li>빠른 접근 제공</li></ul></li><li><p><strong>Level 1 volumes (1차 보조 저장소)</strong>:</p><ul><li>중간 속도 및 비용의 저장소</li><li>압축 형식으로 데이터 저장</li><li>자주 사용되지 않는 데이터 저장</li></ul></li><li><p><strong>Level 2 volumes (2차 보조 저장소)</strong>:</p><ul><li>가장 느리고 저렴한 저장소</li><li>카트리지 기반 테이프 저장소</li><li>거의 사용되지 않는 데이터 저장</li></ul></li></ol><h3 id="데이터-마이그레이션-및-복원-규칙" tabindex="-1"><a class="header-anchor" href="#데이터-마이그레이션-및-복원-규칙"><span>데이터 마이그레이션 및 복원 규칙</span></a></h3><h4 id="데이터-마이그레이션" tabindex="-1"><a class="header-anchor" href="#데이터-마이그레이션"><span>데이터 마이그레이션</span></a></h4><ol><li><p><strong>Primary → Level 1</strong>:</p><ul><li>공간 사용률 또는 데이터 연령을 기반으로 한 임계값에 도달하면</li><li>참조되지 않은 데이터가 Primary volumes에서 Level 1 volumes로 이동</li></ul></li><li><p><strong>Level 1 → Level 2</strong>:</p><ul><li>Level 1 DASD에서 사전 설정된 기간 동안 사용되지 않은 데이터는</li><li>카트리지 기반 저장소(Level 2 volumes)로 이동</li></ul></li></ol><h4 id="데이터-복원" tabindex="-1"><a class="header-anchor" href="#데이터-복원"><span>데이터 복원</span></a></h4><p>어느 단계에서든 데이터가 참조되면, 해당 데이터는 원래 위치(Primary volumes)로 자동 복원됩니다.</p>`,7),r(f,{code:``}),s[23]||=n(`<h3 id="hsm의-주요-기능" tabindex="-1"><a class="header-anchor" href="#hsm의-주요-기능"><span>HSM의 주요 기능</span></a></h3><ol><li><strong>자동 공간 관리</strong>: DASD 공간을 자동으로 관리</li><li><strong>데이터 마이그레이션</strong>: 사용 빈도에 따라 데이터를 적절한 저장소 계층으로 이동</li><li><strong>비용 최적화</strong>: 비용이 많이 드는 저장소 공간을 효율적으로 사용</li><li><strong>자동 복원</strong>: 참조된 데이터를 자동으로 원래 위치로 복원</li><li><strong>압축</strong>: Level 1 저장소에서 데이터 압축으로 공간 절약</li></ol><h3 id="hsm의-이점" tabindex="-1"><a class="header-anchor" href="#hsm의-이점"><span>HSM의 이점</span></a></h3><p>HSM을 사용하면 다음과 같은 이점을 얻을 수 있습니다:</p><ol><li><strong>비용 절감</strong>: 자주 사용되지 않는 데이터를 저렴한 저장소로 이동하여 비용 절감</li><li><strong>성능 향상</strong>: 자주 사용되는 데이터를 빠른 저장소에 유지하여 성능 향상</li><li><strong>자동화</strong>: 수동 개입 없이 자동으로 데이터 관리</li><li><strong>공간 최적화</strong>: 저장소 공간을 효율적으로 활용</li><li><strong>투명성</strong>: 애플리케이션은 데이터 위치를 신경 쓸 필요 없음</li></ol><h3 id="hsm의-작동-원리" tabindex="-1"><a class="header-anchor" href="#hsm의-작동-원리"><span>HSM의 작동 원리</span></a></h3><p>HSM은 다음과 같은 기준으로 데이터를 관리합니다:</p><ul><li><strong>공간 사용률</strong>: 저장소 공간 사용률이 임계값을 초과하면 데이터 마이그레이션</li><li><strong>데이터 연령</strong>: 일정 기간 동안 사용되지 않은 데이터를 자동으로 마이그레이션</li><li><strong>접근 빈도</strong>: 데이터 접근 빈도를 모니터링하여 적절한 저장소 계층으로 이동</li></ul><h3 id="hsm의-중요성" tabindex="-1"><a class="header-anchor" href="#hsm의-중요성"><span>HSM의 중요성</span></a></h3><p>HSM은 대규모 z/OS 환경에서 필수적인 구성 요소입니다:</p><ul><li><strong>저장소 비용 관리</strong>: 저장소 비용을 효율적으로 관리</li><li><strong>성능 최적화</strong>: 자주 사용되는 데이터에 빠른 접근 제공</li><li><strong>자동화</strong>: 수동 관리 작업 감소</li><li><strong>확장성</strong>: 대규모 데이터 환경 지원</li></ul><div class="hint-container tip"><p class="hint-container-title">SMS/HSM 요약</p><ul><li><strong>SMS (Storage Management Subsystem)</strong>: 다양한 IBM 제품을 통합하여 자동 공간 관리를 제공</li><li><strong>HSM (Hierarchical Storage Manager)</strong>: SMS의 구성 요소로, DFSMShsm으로도 알려짐</li><li><strong>계층적 저장소 구조</strong>: <ul><li>Primary volumes: 빠르고 비용이 많이 드는 저장소</li><li>Level 1 volumes: 중간 속도 및 비용의 압축 저장소</li><li>Level 2 volumes: 느리고 저렴한 카트리지 테이프 저장소</li></ul></li><li><strong>작동 방식</strong>: <ul><li>공간 사용률 또는 데이터 연령을 기반으로 데이터 마이그레이션</li><li>데이터 참조 시 자동으로 원래 위치로 복원</li></ul></li><li><strong>주요 기능</strong>: 자동 공간 관리, 데이터 마이그레이션, 비용 최적화, 자동 복원</li></ul></div><h2 id="summary-요약" tabindex="-1"><a class="header-anchor" href="#summary-요약"><span>Summary (요약)</span></a></h2><h3 id="모듈-개요" tabindex="-1"><a class="header-anchor" href="#모듈-개요"><span>모듈 개요</span></a></h3><p>이 모듈에서는 운영 체제와 결합하여 완전한 컴퓨팅 환경에 필요한 시설을 제공하는 많은 제품들을 탐구했습니다.</p><h3 id="주요-학습-내용" tabindex="-1"><a class="header-anchor" href="#주요-학습-내용"><span>주요 학습 내용</span></a></h3><h4 id="_1-subsystems-서브시스템" tabindex="-1"><a class="header-anchor" href="#_1-subsystems-서브시스템"><span>1. Subsystems (서브시스템)</span></a></h4><ul><li><strong>Primary Subsystem</strong>: 모든 z/OS 설치에 필수인 Job Entry Subsystem (JES)</li><li><strong>Secondary Subsystems</strong>: SMS(HSM 포함), RACF, WLM 등 선택적 서브시스템</li><li>서브시스템은 다른 구성 요소와 비동기적으로 작동하는 시스템 구성 요소</li></ul><h4 id="_2-job-control-language-jcl" tabindex="-1"><a class="header-anchor" href="#_2-job-control-language-jcl"><span>2. Job Control Language (JCL)</span></a></h4><ul><li>z/OS 시스템의 핵심 언어</li><li>작업의 리소스 요구 사항을 정의</li><li>JOB 문, EXEC 문, DD 문으로 구성</li><li>모든 작업 실행에 필수</li></ul><h4 id="_3-tso-e-and-ispf" tabindex="-1"><a class="header-anchor" href="#_3-tso-e-and-ispf"><span>3. TSO/E and ISPF</span></a></h4><ul><li><strong>TSO/E</strong>: 프로그래머나 운영자가 z/OS 프로그램과 대화형으로 작업할 수 있게 해주는 도구</li><li><strong>ISPF</strong>: TSO/E 하에서 실행되는 메뉴 기반 인터페이스</li><li>데이터셋 생성, 소스 코드 작성, JCL 작성, 작업 제출 기능 제공</li></ul><h4 id="_4-vtam-and-tcp-ip" tabindex="-1"><a class="header-anchor" href="#_4-vtam-and-tcp-ip"><span>4. VTAM and TCP/IP</span></a></h4><ul><li><strong>VTAM</strong>: 채널과 LAN 연결 장치 간의 데이터 전송 관리 및 SNA 라우팅</li><li><strong>TCP/IP</strong>: 비독점 표준 네트워크 프로토콜</li><li><strong>z/OS Communications Server</strong>: VTAM과 TCP/IP를 통합한 단일 제품</li></ul><h4 id="_5-system-log-syslog" tabindex="-1"><a class="header-anchor" href="#_5-system-log-syslog"><span>5. System Log (SYSLOG)</span></a></h4><ul><li>프로그램, 운영자, 시스템 간의 통신 기록</li><li>SDSF에서 <code>LOG</code> 명령으로 접근</li><li>운영자 작업, 작업 시간, WTO/WTOR 메시지 등 기록</li></ul><h4 id="_6-system-automation" tabindex="-1"><a class="header-anchor" href="#_6-system-automation"><span>6. System Automation</span></a></h4><ul><li>여러 시스템의 콘솔 메시지를 상관관계 분석하고 필터링</li><li>일상적인 문제에 대한 자동 응답 및 작업 수행</li><li>IBM Z System Automation, Broadcom&#39;s OPS/MVS, BMC AMI Ops 등</li></ul><h4 id="_7-cics-customer-information-control-system" tabindex="-1"><a class="header-anchor" href="#_7-cics-customer-information-control-system"><span>7. CICS (Customer Information Control System)</span></a></h4><ul><li>고속 트랜잭션 처리 시스템</li><li>VTAM 또는 TCP/IP와 함께 작동</li><li>초당 수천 개의 트랜잭션 처리 가능</li><li>다양한 프로그래밍 언어 지원</li></ul><h4 id="_8-ims-information-management-system" tabindex="-1"><a class="header-anchor" href="#_8-ims-information-management-system"><span>8. IMS (Information Management System)</span></a></h4><ul><li>온라인 애플리케이션 및 데이터베이스 관리 시스템</li><li>CICS의 트랜잭션 처리 기능과 Db2의 데이터베이스 관리 기능 제공</li><li>여러 데이터베이스와 양방향 통신</li></ul><h4 id="_9-db2" tabindex="-1"><a class="header-anchor" href="#_9-db2"><span>9. Db2</span></a></h4><ul><li>SQL로 구동되는 관계형 데이터베이스 관리 시스템</li><li>크로스 플랫폼 지원</li><li>다양한 데이터 타입 지원 (구조화된 데이터, 이미지, 텍스트, 비디오, XML 등)</li><li>Tables, Tables spaces, Storage groups, Views, Indexes 구성</li></ul><h4 id="_10-ibm-mq" tabindex="-1"><a class="header-anchor" href="#_10-ibm-mq"><span>10. IBM MQ</span></a></h4><ul><li>Message Queuing을 의미하며, MQSeries에서 시작</li><li>다양한 플랫폼 간 메시지 통신 지원</li><li>비동기 통신 및 신뢰성 있는 메시지 전달</li></ul><h4 id="_11-security-보안" tabindex="-1"><a class="header-anchor" href="#_11-security-보안"><span>11. Security (보안)</span></a></h4><ul><li>z/OS 자체는 보안 기능을 제공하지 않음</li><li>별도의 보안 제품 필요: <ul><li>IBM Security Server (RACF)</li><li>Broadcom&#39;s ACF2</li><li>Broadcom&#39;s Top Secret</li></ul></li><li>사용자 인증, 데이터셋 보안, 접근 제어 기능 제공</li></ul><h4 id="_12-sms-hsm" tabindex="-1"><a class="header-anchor" href="#_12-sms-hsm"><span>12. SMS/HSM</span></a></h4><ul><li><strong>SMS</strong>: 자동 공간 관리를 제공하는 시스템</li><li><strong>HSM</strong>: 계층적 저장소 관리자</li><li>3단계 저장소 구조: Primary volumes → Level 1 volumes → Level 2 volumes</li><li>자동 데이터 마이그레이션 및 복원</li></ul><h3 id="학습-목표-달성" tabindex="-1"><a class="header-anchor" href="#학습-목표-달성"><span>학습 목표 달성</span></a></h3><p>이 모듈을 완료한 후, 다음을 수행할 수 있습니다:</p><ul><li><strong>가장 널리 사용되는 z/OS 시스템 구성 요소의 이름과 기능을 식별할 수 있습니다</strong></li></ul><h3 id="주요-구성-요소-요약표" tabindex="-1"><a class="header-anchor" href="#주요-구성-요소-요약표"><span>주요 구성 요소 요약표</span></a></h3><table><thead><tr><th>구성 요소</th><th>주요 기능</th></tr></thead><tbody><tr><td><strong>JES</strong></td><td>작업 입력 및 출력 관리</td></tr><tr><td><strong>JCL</strong></td><td>작업의 리소스 요구 사항 정의</td></tr><tr><td><strong>TSO/E</strong></td><td>대화형 작업 환경 제공</td></tr><tr><td><strong>ISPF</strong></td><td>메뉴 기반 인터페이스 제공</td></tr><tr><td><strong>VTAM</strong></td><td>통신 중개 및 SNA 라우팅</td></tr><tr><td><strong>TCP/IP</strong></td><td>표준 네트워크 통신</td></tr><tr><td><strong>CICS</strong></td><td>고속 트랜잭션 처리</td></tr><tr><td><strong>IMS</strong></td><td>트랜잭션 처리 및 데이터베이스 관리</td></tr><tr><td><strong>Db2</strong></td><td>관계형 데이터베이스 관리</td></tr><tr><td><strong>IBM MQ</strong></td><td>메시지 큐잉 및 통신</td></tr><tr><td><strong>RACF/ACF2/Top Secret</strong></td><td>보안 및 접근 제어</td></tr><tr><td><strong>SMS/HSM</strong></td><td>자동 저장소 관리</td></tr></tbody></table><h3 id="결론" tabindex="-1"><a class="header-anchor" href="#결론"><span>결론</span></a></h3><p>z/OS 시스템은 운영 체제와 함께 작동하는 다양한 제품들로 구성된 완전한 컴퓨팅 환경을 제공합니다. 이러한 구성 요소들은 각각 고유한 기능을 제공하며, 함께 작동하여 엔터프라이즈급 컴퓨팅 환경을 구축합니다.</p>`,47)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};